(typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = \"\xF0\x9F\x8E\xA3 \" .. eventName .. \" Found!\",\n                description = \"An event NPC has just appeared in the server. Join fast!\",\n                color = 0xFF6B35,\n                fields = {\n                    { name = \"\xF0\x9F\x94\x97 Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\xF0\x9F\x91\xA5 Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\xE2\x8F\xB0 Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Event Scanner\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendWeatherWebhook(url, weatherName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local weatherEmoji = {\n            [\"Rainy\"] = \"\xF0\x9F\x8C\xA7\xEF\xB8\x8F\", [\"Thunderstorm\"] = \"\xE2\x9B\x88\xEF\xB8\x8F\", [\"Foggy\"] = \"\xF0\x9F\x8C\xAB\xEF\xB8\x8F\",\n            [\"Windy\"] = \"\xF0\x9F\x92\xA8\", [\"Snowy\"] = \"\xE2\x9D\x84\xEF\xB8\x8F\", [\"Blazing Sun\"] = \"\xE2\x98\x80\xEF\xB8\x8F\"\n        }\n        local colors = {\n            [\"Rainy\"] = 0x2A75BB, [\"Thunderstorm\"] = 0x800080, [\"Foggy\"] = 0x808080,\n            [\"Windy\"] = 0x87CEEB, [\"Snowy\"] = 0xFFFAFA, [\"Blazing Sun\"] = 0xFF4500\n        }\n        local emoji = weatherEmoji[weatherName] or \"\xF0\x9F\x8C\xA6\xEF\xB8\x8F\"\n        local embedColor = colors[weatherName] or 0x00A2FF\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = emoji .. \" Weather Alert: \" .. weatherName .. \"!\",\n                description = \"Special weather is active right now. Perfect time to fish!\",\n                color = embedColor,\n                fields = {\n                    { name = \"\xF0\x9F\x94\x97 Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\xF0\x9F\x91\xA5 Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\xE2\x8F\xB0 Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Weather Alert\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendSpiritWebhook()\n        sendDiscordWebhook(SPIRIT_WEBHOOK, \"SPIRIT\")\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild(\"PlayerGui\") and lp.PlayerGui:FindFirstChild(\"MainGui\")\n        if mg then\n            local info = mg:FindFirstChild(\"Info\")\n            if info then\n                local infoFrame = info:FindFirstChild(\"Info\")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild(\"Value\")\n                        if val then\n                            local text = val:IsA(\"TextLabel\") and val.Text or val.Value\n                            return text:gsub(\"Weather:%s*\", \"\")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendDiscordWebhook(MAOSHAN_WEBHOOK, \"Maoshan NPC\")\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendDiscordWebhook(TAOIST_WEBHOOK, \"Taoist NPC\")\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild(\"NPC\")\n                if npcF and npcF:FindFirstChild(\"God\") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendSpiritWebhook()\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= \"Clear\" and uiWeather ~= \"\" then\n                current = uiWeather\n            else\n                for _, w in ipairs({\"Rainy\", \"Thunderstorm\", \"Foggy\", \"Windy\", \"Snowy\", \"Blazing Sun\"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= \"clear\" then\n            NexusState.LastWeather = current\n            sendWeatherWebhook(WEATHER_WEBHOOK, current)\n        end\n    end\n\n    task.spawn(function()\n        local npcFolder = Workspace:WaitForChild(\"NPC\", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild(\"PlayerGui\", 30):WaitForChild(\"MainGui\", 30)\n            local info = mg and mg:WaitForChild(\"Info\", 15)\n            local infoFrame = info and info:WaitForChild(\"Info\", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild(\"Weather\", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild(\"Value\", 15)\n            if val then\n                local signal = val:IsA(\"TextLabel\") and val:GetPropertyChangedSignal(\"Text\") or val:GetPropertyChangedSignal(\"Value\")\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\nTravar barra de capturaCh\xE1\xBB\x8Dn NPC h\xE1\xBB\x8Dc chi\xC3\xAAuAuto Farm Cuaca RahasiaAuto Rezar al Esp\xC3\xADrituAllowed Weather IslandsIdioma y Localizaci\xC3\xB3nS\xE1\xBB\x91 m\xE1\xBB\x93i c\xE1\xBA\xA7n ch\xE1\xBA\xBFUpgrade Selected SkillActivar NotificacionesN\xC3\xA2ng c\xE1\xBA\xA5p k\xE1\xBB\xB9 n\xC4\x83ngSelect Skills to LearnUpgraded successfully!Auto Kelahiran KembaliCh\xE1\xBA\xBF t\xE1\xBA\xA1o m\xE1\xBB\x93i c\xC3\xA2uIdioma e Localiza\xC3\xA7\xC3\xA3oCh\xE1\xBB\x8Dn m\xE1\xBB\x93i c\xE1\xBA\xA7n muaResumen de la sesi\xC3\xB3nPh\xC6\xB0\xC6\xA1ng ph\xC3\xA1p b\xC3\xA1n 2Auto Favoritar PeixesUpdateFishProgressionAuto pescar materiaisAuto Pulpo Sin NombreFolder God not found!\xE0\xB8\xA3\xE0\xB9\x89\xE0\xB8\xB2\xE0\xB8\x99\xE0\xB8\x84\xE0\xB9\x89\xE0\xB8\xB2Kunci bilah tangkapanLearn Selected SkillsSage Yijiu not found!Enable Auto Farm FishSafe band (0.01-0.17)Auto Farm Secret BossCh\xE1\xBA\xBF \xC4\x91\xE1\xBB\x99 Bay (Fly)Ch\xE1\xBB\x8Dn ng\xC6\xB0\xE1\xBB\x9Di ch\xC6\xA1iNameless OctoparasiteOrdem das HabilidadesBoss daily completed!Ativar Notifica\xC3\xA7\xC3\xB5esflyInputEndConnectionSkill Delay (seconds)ChooseDialogueOptionAuto Favoritkan IkanCharacter not found!Auto Enzo Fight ModeNexusBossFightThreadAuto Equip Best BaitPasang Umpan TerbaikNexus: Thong bao keyBerjalan di Atas AirReroll \xC4\x91\xE1\xBA\xBFn khi raEnable NotificationsBay t\xE1\xBB\x9Bi \xC4\x90\xE1\xBA\xA1o S\xC4\xA9Notas de la versi\xC3\xB3nAuto (Roblox Locale)No Secret Rods foundAll materials ready!Heavenpiercer TurtleT\xE1\xBB\xB1 gi\xE1\xBA\xA3i QTE EnzoPlaye